package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"

	"gopkg.in/yaml.v3"
)

// header opens the generated file: the licence lines, then the @file
// header the TypeScript baseline asks for.
const header = `// SPDX-License-Identifier: AGPL-3.0-or-later
// Copyright (C) 2026 The Massimo Authors

/**
 * @file internal/server/ui/src/api.d.ts
 *
 * The API's shapes as TypeScript: one declaration per schema of
 * docs/api-v1-openapi.yaml (components.schemas), in the file's order.
 * Generated by tools/apitypes from the OpenAPI file; not edited by hand:
 * make api-types writes it again.
 */
`

// refPrefix is the start of every $ref the generator follows.
const refPrefix = "#/components/schemas/"

// ignored are the keywords that constrain a value without changing its
// TypeScript shape, and the examples, which stay out of the output.
var ignored = []string{"example", "maxItems", "maxLength", "maximum", "minLength", "minimum", "multipleOf", "pattern"}

// The keywords each kind of schema may carry besides the ignored ones;
// any other stops the generator.
var (
	refKeys    = []string{"$ref"}
	allOfKeys  = []string{"allOf", "description", "nullable"}
	enumKeys   = []string{"enum", "type", "description", "format", "nullable"}
	scalarKeys = []string{"type", "description", "format", "nullable"}
	arrayKeys  = []string{"type", "items", "description", "nullable"}
	objectKeys = []string{"type", "properties", "required", "additionalProperties", "description", "nullable"}
	anyKeys    = []string{"description", "nullable"}
)

// identRE matches a name TypeScript takes unquoted.
var identRE = regexp.MustCompile(`^[A-Za-z_$][A-Za-z0-9_$]*$`)

// generate returns the TypeScript declarations of the schemas of spec,
// an OpenAPI 3.0 document, and how many declarations it wrote. A keyword
// it does not map stops it with an error naming the schema and the
// keyword.
func generate(spec []byte) ([]byte, int, error) {
	var doc yaml.Node
	if err := yaml.Unmarshal(spec, &doc); err != nil {
		return nil, 0, fmt.Errorf("apitypes: the OpenAPI file does not parse: %w", err)
	}
	if len(doc.Content) != 1 {
		return nil, 0, errors.New("apitypes: the OpenAPI file is empty")
	}
	schemas := get(get(doc.Content[0], "components"), "schemas")
	if schemas == nil || schemas.Kind != yaml.MappingNode || len(schemas.Content) == 0 {
		return nil, 0, errors.New("apitypes: the OpenAPI file has no components.schemas")
	}
	var b strings.Builder
	b.WriteString(header)
	n := 0
	for i := 0; i+1 < len(schemas.Content); i += 2 {
		name, s := schemas.Content[i].Value, schemas.Content[i+1]
		if !identRE.MatchString(name) {
			return nil, 0, fmt.Errorf("apitypes: schema %q: the name is not a TypeScript name", name)
		}
		decl, err := declaration(name, s)
		if err != nil {
			return nil, 0, err
		}
		b.WriteString("\n" + decl)
		n++
	}
	return []byte(b.String()), n, nil
}

// declaration is the exported declaration of the schema name: an
// interface for an object with properties, or for an allOf of named
// schemas and at most one object with properties; a type alias for
// anything else.
func declaration(name string, s *yaml.Node) (string, error) {
	if err := isMapping(name, s); err != nil {
		return "", err
	}
	doc := comment(s, "")
	if !isTrue(get(s, "nullable")) {
		if get(s, "properties") != nil && kind(s) == "object" {
			body, err := object(name, s, "")
			if err != nil {
				return "", err
			}
			return doc + "export interface " + name + " " + body + "\n", nil
		}
		if bases, own, ok := extends(s); ok {
			if err := only(name, s, allOfKeys); err != nil {
				return "", err
			}
			body := "{}"
			if own != nil {
				var err error
				if body, err = object(name+".allOf", own, ""); err != nil {
					return "", err
				}
			}
			return doc + "export interface " + name + " extends " + strings.Join(bases, ", ") + " " + body + "\n", nil
		}
	}
	t, err := expr(name, s, "")
	if err != nil {
		return "", err
	}
	return doc + "export type " + name + " = " + t + ";\n", nil
}

// extends reads an allOf that an interface can extend: every member a
// bare $ref, but at most one object with properties, its own members.
func extends(s *yaml.Node) (bases []string, own *yaml.Node, ok bool) {
	all := get(s, "allOf")
	if all == nil || all.Kind != yaml.SequenceNode {
		return nil, nil, false
	}
	for _, m := range all.Content {
		if ref := get(m, "$ref"); ref != nil && len(keys(m)) == 1 {
			name, ok := strings.CutPrefix(ref.Value, refPrefix)
			if !ok || !identRE.MatchString(name) {
				return nil, nil, false
			}
			bases = append(bases, name)
		} else if own == nil && get(m, "properties") != nil && kind(m) == "object" {
			own = m
		} else {
			return nil, nil, false
		}
	}
	return bases, own, len(bases) > 0
}

// expr is the TypeScript type of the schema s, at the path where (for
// errors), its object literals indented from indent.
func expr(where string, s *yaml.Node, indent string) (string, error) {
	if err := isMapping(where, s); err != nil {
		return "", err
	}
	var t string
	var err error
	switch k := kind(s); k {
	case "$ref":
		if err := only(where, s, refKeys); err != nil {
			return "", err
		}
		return refName(where, get(s, "$ref"))
	case "allOf":
		t, err = allOf(where, s, indent)
	case "enum":
		t, err = enum(where, s)
	case "string", "integer", "number", "boolean":
		err = only(where, s, scalarKeys)
		t = map[string]string{"string": "string", "integer": "number", "number": "number", "boolean": "boolean"}[k]
	case "array":
		t, err = array(where, s, indent)
	case "object":
		t, err = object(where, s, indent)
	case "":
		err = only(where, s, anyKeys)
		t = "unknown"
	default:
		err = fmt.Errorf("apitypes: schema %s: type %q is not mapped", where, k)
	}
	if err != nil {
		return "", err
	}
	if isTrue(get(s, "nullable")) {
		if strings.Contains(t, " & ") {
			t = "(" + t + ")"
		}
		t += " | null"
	}
	return t, nil
}

// kind says what the schema s is: "$ref", "allOf", "enum", the value of
// its type (object where it has properties and no type), or "" where it
// says nothing of its type.
func kind(s *yaml.Node) string {
	switch {
	case get(s, "$ref") != nil:
		return "$ref"
	case get(s, "allOf") != nil:
		return "allOf"
	case get(s, "enum") != nil:
		return "enum"
	case get(s, "type") != nil:
		return get(s, "type").Value
	case get(s, "properties") != nil:
		return "object"
	}
	return ""
}

// allOf is the intersection of the members of an allOf.
func allOf(where string, s *yaml.Node, indent string) (string, error) {
	if err := only(where, s, allOfKeys); err != nil {
		return "", err
	}
	all := get(s, "allOf")
	if all.Kind != yaml.SequenceNode || len(all.Content) == 0 {
		return "", fmt.Errorf("apitypes: schema %s: allOf is not a list of schemas", where)
	}
	var parts []string
	for i, m := range all.Content {
		p, err := expr(fmt.Sprintf("%s.allOf[%d]", where, i), m, indent)
		if err != nil {
			return "", err
		}
		if strings.Contains(p, " | ") {
			p = "(" + p + ")"
		}
		parts = append(parts, p)
	}
	return strings.Join(parts, " & "), nil
}

// array is the type of an array's items, then [].
func array(where string, s *yaml.Node, indent string) (string, error) {
	if err := only(where, s, arrayKeys); err != nil {
		return "", err
	}
	items := get(s, "items")
	if items == nil {
		return "", fmt.Errorf("apitypes: schema %s: an array without items", where)
	}
	t, err := expr(where+"[]", items, indent)
	if err != nil {
		return "", err
	}
	if strings.ContainsAny(t, "|&") {
		t = "(" + t + ")"
	}
	return t + "[]", nil
}

// object is the object literal of the properties of s, each with its
// comment and optional unless required names it; without properties, a
// Record of what additionalProperties allows.
func object(where string, s *yaml.Node, indent string) (string, error) {
	if err := only(where, s, objectKeys); err != nil {
		return "", err
	}
	if t := get(s, "type"); t != nil && t.Value != "object" {
		return "", fmt.Errorf("apitypes: schema %s: properties on type %q is not mapped", where, t.Value)
	}
	ap := get(s, "additionalProperties")
	props := get(s, "properties")
	if props == nil {
		switch {
		case get(s, "required") != nil:
			return "", fmt.Errorf("apitypes: schema %s: required without properties is not mapped", where)
		case ap == nil || isTrue(ap):
			return "Record<string, unknown>", nil
		case ap.Kind == yaml.ScalarNode:
			return "", fmt.Errorf("apitypes: schema %s: additionalProperties: %s without properties is not mapped", where, ap.Value)
		}
		t, err := expr(where+"{}", ap, indent)
		if err != nil {
			return "", err
		}
		return "Record<string, " + t + ">", nil
	}
	if ap != nil && !(ap.Kind == yaml.ScalarNode && ap.Value == "false") {
		return "", fmt.Errorf("apitypes: schema %s: additionalProperties beside properties is not mapped", where)
	}
	if props.Kind != yaml.MappingNode {
		return "", fmt.Errorf("apitypes: schema %s: properties is not a mapping", where)
	}
	var names []string
	for i := 0; i+1 < len(props.Content); i += 2 {
		names = append(names, props.Content[i].Value)
	}
	required := map[string]bool{}
	if r := get(s, "required"); r != nil {
		if r.Kind != yaml.SequenceNode {
			return "", fmt.Errorf("apitypes: schema %s: required is not a list", where)
		}
		for _, n := range r.Content {
			if !slices.Contains(names, n.Value) {
				return "", fmt.Errorf("apitypes: schema %s: required names %q, which is not a property", where, n.Value)
			}
			required[n.Value] = true
		}
	}
	inner := indent + "  "
	var b strings.Builder
	b.WriteString("{\n")
	for i, name := range names {
		p := props.Content[2*i+1]
		t, err := expr(where+"."+name, p, inner)
		if err != nil {
			return "", err
		}
		key := name
		if !identRE.MatchString(name) {
			q, _ := json.Marshal(name)
			key = string(q)
		}
		if !required[name] {
			key += "?"
		}
		b.WriteString(comment(p, inner))
		b.WriteString(inner + key + ": " + t + ";\n")
	}
	b.WriteString(indent + "}")
	return b.String(), nil
}

// enum is the union of the literals of an enum of strings or integers.
func enum(where string, s *yaml.Node) (string, error) {
	if err := only(where, s, enumKeys); err != nil {
		return "", err
	}
	typ := ""
	if n := get(s, "type"); n != nil {
		typ = n.Value
	}
	e := get(s, "enum")
	if e.Kind != yaml.SequenceNode || len(e.Content) == 0 {
		return "", fmt.Errorf("apitypes: schema %s: enum is not a list of values", where)
	}
	var lits []string
	for _, v := range e.Content {
		switch {
		case typ == "string" && v.Kind == yaml.ScalarNode:
			q, _ := json.Marshal(v.Value)
			lits = append(lits, string(q))
		case typ == "integer" && v.Tag == "!!int":
			lits = append(lits, v.Value)
		default:
			return "", fmt.Errorf("apitypes: schema %s: enum of type %q with the value %q is not mapped", where, typ, v.Value)
		}
	}
	return strings.Join(lits, " | "), nil
}

// comment is the JSDoc comment of a schema's description and format,
// indented by indent, or nothing where it has neither.
func comment(s *yaml.Node, indent string) string {
	var lines []string
	if d := get(s, "description"); d != nil {
		for _, l := range strings.Split(strings.TrimRight(d.Value, "\n"), "\n") {
			l = strings.ReplaceAll(strings.TrimRight(l, " \t"), "*/", `*\/`)
			lines = append(lines, wrap(l, width-len(indent)-3)...)
		}
	}
	if f := get(s, "format"); f != nil {
		lines = append(lines, "@format "+f.Value)
	}
	switch {
	case len(lines) == 0:
		return ""
	case len(lines) == 1 && len(indent)+len(lines[0])+7 <= width:
		return indent + "/** " + lines[0] + " */\n"
	}
	var b strings.Builder
	b.WriteString(indent + "/**\n")
	for _, l := range lines {
		if l == "" {
			b.WriteString(indent + " *\n")
		} else {
			b.WriteString(indent + " * " + l + "\n")
		}
	}
	b.WriteString(indent + " */\n")
	return b.String()
}

// width is the column a comment's lines are wrapped before.
const width = 80

// wrap breaks the line l at spaces into lines of at most n bytes; a word
// longer than n stands on a line of its own.
func wrap(l string, n int) []string {
	words := strings.Fields(l)
	if len(words) == 0 {
		return []string{""}
	}
	var out []string
	line := words[0]
	for _, w := range words[1:] {
		if len(line)+1+len(w) > n {
			out = append(out, line)
			line = w
		} else {
			line += " " + w
		}
	}
	return append(out, line)
}

// only stops on a keyword of s that is neither in allowed nor ignored.
func only(where string, s *yaml.Node, allowed []string) error {
	for _, k := range keys(s) {
		if !slices.Contains(allowed, k) && !slices.Contains(ignored, k) {
			return fmt.Errorf("apitypes: schema %s: keyword %s is not mapped", where, k)
		}
	}
	return nil
}

// isMapping stops on a schema that is not a mapping, an alias among them.
func isMapping(where string, s *yaml.Node) error {
	if s == nil || s.Kind != yaml.MappingNode {
		return fmt.Errorf("apitypes: schema %s: not a mapping", where)
	}
	return nil
}

// isTrue says whether n is the boolean true.
func isTrue(n *yaml.Node) bool {
	return n != nil && n.Kind == yaml.ScalarNode && n.Value == "true"
}

// refName is the schema a $ref names.
func refName(where string, ref *yaml.Node) (string, error) {
	name, ok := strings.CutPrefix(ref.Value, refPrefix)
	if !ok || !identRE.MatchString(name) {
		return "", fmt.Errorf("apitypes: schema %s: $ref %q is not a schema of components.schemas", where, ref.Value)
	}
	return name, nil
}

// get is the value of key in the mapping m, or nil.
func get(m *yaml.Node, key string) *yaml.Node {
	if m == nil || m.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(m.Content); i += 2 {
		if m.Content[i].Value == key {
			return m.Content[i+1]
		}
	}
	return nil
}

// keys are the keys of the mapping m, in order.
func keys(m *yaml.Node) []string {
	var out []string
	for i := 0; i+1 < len(m.Content); i += 2 {
		out = append(out, m.Content[i].Value)
	}
	return out
}
